import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.y1bVONfd.js";const u=JSON.parse('{"title":"Roadmap to npm","description":"","frontmatter":{},"headers":[],"relativePath":"roadmap.md","filePath":"roadmap.md"}'),d={name:"roadmap.md"};function n(s,t,i,l,h,p){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="roadmap-to-npm" tabindex="-1">Roadmap to npm <a class="header-anchor" href="#roadmap-to-npm" aria-label="Permalink to &quot;Roadmap to npm&quot;">​</a></h1><p>This is the <strong>product</strong> roadmap: what ships, in what order, on the way to a published <code>npm</code> package you can run with <code>npx proofmark</code>. It covers shipped behavior and planned work only — it makes no claims about features that don&#39;t exist yet.</p><p>Status legend:</p><ul><li>✅ <strong>Shipped</strong> — available today on <code>main</code>.</li><li>🚧 <strong>In progress</strong> — partially built, not yet complete.</li><li>🔭 <strong>Planned</strong> — designed, not yet built.</li></ul><blockquote><p>Today Proofmark runs from a clone (<code>npm run cli -- ...</code>). The headline goal of this roadmap is the first published release: <code>npx proofmark</code> with no clone.</p></blockquote><h2 id="now-—-alpha-prisma-postgres-dry-run" tabindex="-1">Now — Alpha (Prisma + Postgres, dry-run) <a class="header-anchor" href="#now-—-alpha-prisma-postgres-dry-run" aria-label="Permalink to &quot;Now — Alpha (Prisma + Postgres, dry-run)&quot;">​</a></h2><p>The current supported path. All of this works today.</p><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td>Prisma schema discovery and masking-rule inference</td><td>✅ Shipped</td></tr><tr><td>Read-only Postgres sampling</td><td>✅ Shipped</td></tr><tr><td>HMAC-keyed deterministic masking (fails closed without a workspace seed)</td><td>✅ Shipped</td></tr><tr><td>CLI evidence output with a Proofmark Certificate</td><td>✅ Shipped</td></tr><tr><td><code>init</code> generates <code>proofmark.json</code> + a gitignored <code>PROOFMARK_WORKSEED</code></td><td>✅ Shipped</td></tr><tr><td>Runnable example Prisma/Postgres project</td><td>✅ Shipped</td></tr></tbody></table><p>Masking is deterministic, transparent, and stateless — no real-to-fake values are ever stored. See <a href="/docs/solution.html">How masking works</a> for the algorithm and the security model, including what a leaked seed does and does not expose.</p><h2 id="next-—-first-npm-release" tabindex="-1">Next — First npm release <a class="header-anchor" href="#next-—-first-npm-release" aria-label="Permalink to &quot;Next — First npm release&quot;">​</a></h2><p>The work that turns &quot;clone and run&quot; into &quot;install and run.&quot;</p><table tabindex="0"><thead><tr><th>Milestone</th><th>Status</th><th>Notes</th></tr></thead><tbody><tr><td>Publish CLI to npm so <code>npx proofmark</code> works without cloning</td><td>🔭 Planned</td><td>The dry run today is local; this is the gate to public install.</td></tr><tr><td>Public demo route that renders <strong>real</strong> dry-run evidence (not mocked)</td><td>🚧 In progress</td><td>Example project shipped; the public demo route is still deferred.</td></tr><tr><td>Quickstart and CLI reference docs on proofmark.dev/docs</td><td>🚧 In progress</td><td>This docs site.</td></tr></tbody></table><h3 id="what-ready-for-npm-means" tabindex="-1">What &quot;ready for npm&quot; means <a class="header-anchor" href="#what-ready-for-npm-means" aria-label="Permalink to &quot;What &quot;ready for npm&quot; means&quot;">​</a></h3><p>A release is publishable when:</p><ol><li><code>npx proofmark init</code> → <code>pull --dry-run</code> works against a real Prisma/Postgres database from a clean machine.</li><li>A non-demo dry run with no resolvable <code>PROOFMARK_WORKSEED</code> exits non-zero with a clear error (fails closed).</li><li><code>npm pack --dry-run</code> ships only the CLI surface — no internal tooling, planning notes, or experimental dashboard code.</li><li>README and docs describe only shipped behavior, with planned items clearly marked.</li></ol><h2 id="later-—-after-v1" tabindex="-1">Later — After v1 <a class="header-anchor" href="#later-—-after-v1" aria-label="Permalink to &quot;Later — After v1&quot;">​</a></h2><p>Larger capabilities that extend Proofmark beyond a read-only dry run. These are designed, not built — they are not promised in any current release.</p><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th><th>Notes</th></tr></thead><tbody><tr><td>Write/seed mode — load masked sample data into a local or target database</td><td>🔭 Planned</td><td>Today&#39;s path is dry-run only; nothing is written to source or target.</td></tr><tr><td>Additional schema adapters beyond Prisma</td><td>🔭 Planned</td><td>The dry-run sampler is Prisma-only today.</td></tr><tr><td>Additional source databases beyond Postgres</td><td>🔭 Planned</td><td></td></tr><tr><td>Plugin API for custom maskers</td><td>🔭 Planned</td><td>Documented as planned in <a href="/docs/solution.html">How masking works</a>; not yet implemented.</td></tr></tbody></table><h2 id="out-of-scope-here" tabindex="-1">Out of scope here <a class="header-anchor" href="#out-of-scope-here" aria-label="Permalink to &quot;Out of scope here&quot;">​</a></h2><p>Go-to-market plans, launch sequencing, pricing, and funding are tracked privately, not in this repo or on this site. This page stays focused on the product.</p><h2 id="want-to-influence-this" tabindex="-1">Want to influence this? <a class="header-anchor" href="#want-to-influence-this" aria-label="Permalink to &quot;Want to influence this?&quot;">​</a></h2><p>Open an issue or start a discussion on <a href="https://github.com/watthem/proofmark" target="_blank" rel="noreferrer">GitHub</a>. The most useful contribution right now: bring a messy table that makes local testing painful, and a dry run should prove your app still works without keeping the real identifiers.</p>',22)])])}const m=e(d,[["render",n]]);export{u as __pageData,m as default};
